full := (tempCount = 8);
empty := (tempCount = 0);

IF tempCount = 0 THEN
    head := 0;
ELSE
    head := tempFifo[1];
END_IF

fifo := tempFifo;
actualCount := tempCount;

prevPush := pushEn;
prevPop := popEn;
